41	template <pipe_t srcPipe, pipe_t dstPipe>
42	AICORE inline void SetFlag(uint32_t id)
43	{
44	    set_flag(srcPipe, dstPipe, static_cast<event_t>(id));
45	}
46	template <pipe_t srcPipe, pipe_t dstPipe>
47	
48	AICORE inline void WaitFlag(uint32_t id)
49	{
50	    wait_flag(srcPipe, dstPipe, static_cast<event_t>(id));
51	}
