32	    static constexpr bool is_both = (DIR_TYPE == Direction::DIR_BOTH);         // 3
33	    static constexpr bool is_v2c_ctrl = (DIR_TYPE == Direction::DIR_V2C_CTRL); // 4
34	    static constexpr bool is_c2v_gm = (DIR_TYPE == Direction::DIR_C2V_GM);     // 5
35	    static constexpr bool is_v2c_gm = (DIR_TYPE == Direction::DIR_V2C_GM);     // 6
36	    static constexpr bool is_both_gm = (DIR_TYPE == Direction::DIR_BOTH_GM);   // 7
37	    static constexpr uint32_t SyncPeriod = (SlotNum <= 2) ? SlotNum : SlotNum / 2;
38	    static constexpr uint8_t FlagIDPlusOne = FlagID + 1;
39	    static constexpr uint8_t FlagIDPlusTwo = FlagID + 2;
40	    static constexpr uint8_t FlagIDPlusThree = FlagID + 3;
41	    static constexpr bool is_c2v = is_c2v_gm || is_c2v_ub;
42	    static constexpr bool is_v2c = is_v2c_gm || is_v2c_mat || is_v2c_ctrl;
43	    static_assert(
44	        is_c2v || is_v2c || is_both || is_both_gm, "Fix: TPipe only supports C2V or V2C or Both communication on A5.");
45	    static constexpr uint8_t VEC_CORE_ID_OFFSET = 16;
46	    static_assert(
47	        FlagIDPlusOne < 16, "Fix: With Both direction, FlagID + 1 must be less than 16 due to hardware limit.");
