49	    // -------------------------------------------------------------------------
50	    // RingFiFo
51	    // -------------------------------------------------------------------------
52	    using RingFiFo = RingFIFO<SlotSize, SlotNum, LocalSlotNum>;
53	
54	    PTO_INTERNAL static bool shouldWaitFree(uint32_t tileIndex)
55	    {
56	        // Startup protection: Don't check flags when buffer is empty
57	        if (tileIndex < SlotNum) {
58	            return false;
59	        }
60	        // Sparse sync: Only check flags periodically to reduce overhead
61	        return (tileIndex % SyncPeriod) == 0;
62	    }
63	
64	    PTO_INTERNAL static bool shouldNotifyFree(uint32_t tileIndex)
65	    {
66	        // Notify consumer to free buffer when producer is one slot ahead of consumer
67	        return ((tileIndex + 1) % SyncPeriod) == 0;
68	    }
