70	    // -------------------------------------------------------------------------
71	    // Producer Interface
72	    // -------------------------------------------------------------------------
73	    struct Producer {
74	        uint32_t subTileIndex = 0;
75	        uint32_t tileIndex = 0;
76	        bool isRecord = true;
77	        bool isAllocate = true;
78	        int entryOffset = 0;
