97	
98	        PTO_INTERNAL bool getRecordStatus() const { return isRecord; }
99	
100	        PTO_INTERNAL void setEntryOffset(int offset) { entryOffset = offset; }
101	
102	        template <pipe_t Pipe, TileSplitAxis Split>
103	        PTO_INTERNAL static void setIntraBlockBySplit(uint8_t flagId)
104	        {
105	            set_intra_block(Pipe, flagId);
106	            if constexpr (Split != TileSplitAxis::TILE_NO_SPLIT) {
107	                set_intra_block(Pipe, flagId + VEC_CORE_ID_OFFSET);
108	            }
109	        }
110	
111	        template <pipe_t Pipe, TileSplitAxis Split>
112	        PTO_INTERNAL static void waitIntraBlockBySplit(uint8_t flagId)
113	        {
114	            wait_intra_block(Pipe, flagId);
115	            if constexpr (Split != TileSplitAxis::TILE_NO_SPLIT) {
116	                wait_intra_block(Pipe, flagId + VEC_CORE_ID_OFFSET);
117	            }
118	        }
119	
120	        /**
121	         * alloc: Request space in FIFO
122	         * 1. (iter >= Depth): Startup protection. Don't check flags when buffer is empty.
123	         * 2. (iter % Period == 0): Sparse sync. Only check flag periodically.
124	         */
125	        template <TileSplitAxis Split = TileSplitAxis::TILE_UP_DOWN>
126	        PTO_INTERNAL void allocate() const
127	        {
128	            if constexpr (is_c2v) {
129	#ifdef __DAV_CUBE__
130	                waitIntraBlockBySplit<PIPE_FIX, Split>(FlagIDPlusOne);
131	#endif
132	            } else if constexpr (is_v2c_gm || is_v2c_mat) { // is_v2c (both gm and mat)
133	#ifdef __DAV_VEC__
134	                wait_intra_block(PIPE_MTE3, FlagIDPlusOne);
135	#endif
136	            } else if constexpr (is_both) {
137	#ifdef __DAV_CUBE__
138	                waitIntraBlockBySplit<PIPE_FIX, Split>(FlagIDPlusOne);
139	#endif
140	#ifdef __DAV_VEC__
141	                static_assert(
142	                    FlagIDPlusThree < 16,
143	                    "Fix: With Both direction, FlagID + 3 must be less than 16 due to hardware limit.");
144	                wait_intra_block(PIPE_MTE3, FlagIDPlusThree);
145	#endif
146	            } else if constexpr (is_v2c_ctrl) {
147	#ifdef __DAV_VEC__
148	                wait_intra_block(PIPE_S, FlagIDPlusOne);
149	#endif
150	            } else if constexpr (is_both_gm) {
151	#ifdef __DAV_CUBE__
152	                waitIntraBlockBySplit<PIPE_FIX, Split>(FlagIDPlusOne);
153	#endif
154	#ifdef __DAV_VEC__
155	                static_assert(
156	                    FlagIDPlusThree < 16,
157	                    "Fix: With Both direction, FlagID + 3 must be less than 16 due to hardware limit.");
158	                wait_intra_block(PIPE_MTE3, FlagIDPlusThree);
159	#endif
160	            }
161	        }
162	
163	        // Forward dependency: record (producer) and wait (consumer)
164	        /**
165	         * record - Producer signals that data is ready
166	         * Called by the producer after completing the operation (TSTORE_C2GM or TSTORE_V2GM)
167	         */
168	        template <TileSplitAxis Split = TileSplitAxis::TILE_UP_DOWN>
169	        PTO_INTERNAL void record() const
170	        {
171	            if constexpr (is_c2v) {
172	#ifdef __DAV_CUBE__
173	                setIntraBlockBySplit<PIPE_FIX, Split>(FlagID);
174	#endif
175	            } else if constexpr (is_v2c_gm || is_v2c_mat) {
176	                set_intra_block(PIPE_MTE3, FlagID);
177	            } else if constexpr (is_both) {
178	#ifdef __DAV_CUBE__
179	                setIntraBlockBySplit<PIPE_FIX, Split>(FlagID);
180	#endif
181	#ifdef __DAV_VEC__
182	                set_intra_block(PIPE_MTE3, FlagIDPlusTwo);
183	#endif
184	            } else if constexpr (is_v2c_ctrl) {
185	                set_intra_block(PIPE_S, FlagID);
186	            } else if constexpr (is_both_gm) {
187	#ifdef __DAV_VEC__
188	                set_intra_block(PIPE_MTE3, FlagIDPlusTwo);
189	#endif
190	#ifdef __DAV_CUBE__
191	                setIntraBlockBySplit<PIPE_FIX, Split>(FlagID);
192	#endif
193	            }
194	        }
