196	        template <typename TileProd, TileSplitAxis Split>
197	        PTO_INTERNAL void pushAcc2VecFiFo(RingFiFo& fifo, TileProd& tile)
198	        {
199	            using T = typename TileProd::DType;
200	            constexpr int ProdM = TileProd::Rows;
201	            constexpr int ProdN = TileProd::Cols;
202	            constexpr uint32_t splitNum = 2;
203	            constexpr int ConsM = (Split == TileSplitAxis::TILE_UP_DOWN) ? (ProdM / splitNum) : ProdM;
204	            constexpr int ConsN = (Split == TileSplitAxis::TILE_LEFT_RIGHT) ? (ProdN / splitNum) : ProdN;
205	            int vRows = (Split == TileSplitAxis::TILE_UP_DOWN) ? (tile.GetValidRow() / splitNum) : tile.GetValidRow();
206	            int vCols =
207	                (Split == TileSplitAxis::TILE_LEFT_RIGHT) ? (tile.GetValidCol() / splitNum) : tile.GetValidCol();
208	            using TileCons = Tile<TileType::Vec, T, ConsM, ConsN, BLayout::RowMajor, -1, -1>;
209	            TileCons vecTile(vRows, vCols);
210	            uint64_t entryBase = (tileIndex % RingFiFo::SLOT_NUM) * RingFiFo::SLOT_SIZE; // ConsM * ConsN * sizeof(T);
211	            TASSIGN(vecTile, (uint64_t)(fifo.C2V_CONSUMER_BUF + entryBase + entryOffset));
212	
213	            if constexpr (Split == TileSplitAxis::TILE_NO_SPLIT) {
214	                TMOV_IMPL<TileCons, TileProd, AccToVecMode::SingleModeVec0>(vecTile, tile);
215	            } else if constexpr (Split == TileSplitAxis::TILE_UP_DOWN) {
216	                static_assert(
217	                    (ProdM % 2 == 0) && (sizeof(T) == 4),
218	                    "Fix: For C2V(L0C-> UB), only support up-down split with ProdM being multiple of 2 due "
219	                    "to hardware requirement.");
220	                PTO_ASSERT(
221	                    (tile.GetValidRow() % 2 == 0) && (sizeof(T) == 4),
222	                    "Fix: For C2V(L0C-> UB), only support up-down split with ProdM being multiple of 2 due to "
223	                    "hardware requirement.");
224	                TMOV_IMPL<TileCons, TileProd, AccToVecMode::DualModeSplitM>(vecTile, tile);
225	            } else if constexpr (Split == TileSplitAxis::TILE_LEFT_RIGHT) {
226	                static_assert(
227	                    (ProdN % 32 == 0) && (sizeof(T) == 4),
228	                    "Fix: For C2V(L0C-> UB), only support left-right split with ProdN being multiple of 32 "
229	                    "due to hardware requirement.");
230	                PTO_ASSERT(
231	                    (tile.GetValidCol() % 32 == 0) && (sizeof(T) == 4),
232	                    "Fix: For C2V(L0C-> UB), only support left-right split with ProdN being multiple of 32 due "
233	                    "to hardware requirement.");
234	                TMOV_IMPL<TileCons, TileProd, AccToVecMode::DualModeSplitN>(vecTile, tile);
235	            }
236	        }
