238	        template <typename TileProd, TileSplitAxis Split>
239	        PTO_INTERNAL void pushVec2MatFiFo(RingFiFo& fifo, TileProd& tile, int32_t subBlockId)
240	        {
241	            using T = typename TileProd::DType;
242	            constexpr uint32_t splitNum = 2;
243	            constexpr int ConsM = (Split == TileSplitAxis::TILE_UP_DOWN) ? TileProd::Rows * splitNum : TileProd::Rows;
244	            constexpr int ConsN =
245	                (Split == TileSplitAxis::TILE_LEFT_RIGHT) ? TileProd::Cols * splitNum : TileProd::Cols;
246	            int vRows = (Split == TileSplitAxis::TILE_UP_DOWN) ? tile.GetValidRow() * splitNum : tile.GetValidRow();
247	            int vCols = (Split == TileSplitAxis::TILE_LEFT_RIGHT) ? tile.GetValidCol() * splitNum : tile.GetValidCol();
248	            using MatTile = Tile<TileType::Mat, T, ConsM, ConsN, BLayout::ColMajor, -1, -1>;
249	            MatTile matTile(vRows, vCols);
250	            uint64_t entryBase = (tileIndex % RingFiFo::SLOT_NUM) * RingFiFo::SLOT_SIZE; // ConsM * ConsN * sizeof(T);
251	            TASSIGN_IMPL(matTile, (uint64_t)(fifo.V2C_CONSUMER_BUF + entryBase + entryOffset));
252	            if constexpr (Split == TileSplitAxis::TILE_NO_SPLIT) {
253	                // single vector core
254	                TINSERT_IMPL(matTile, tile, static_cast<uint16_t>(0), static_cast<uint16_t>(0));
255	            } else if constexpr (Split == TileSplitAxis::TILE_UP_DOWN) {
256	                int rowIndex = tile.GetValidRow() * static_cast<size_t>(subBlockId);
257	                TINSERT_IMPL(matTile, tile, static_cast<uint16_t>(rowIndex), static_cast<uint16_t>(0));
258	            } else if constexpr (Split == TileSplitAxis::TILE_LEFT_RIGHT) {
259	                PTO_ASSERT(
260	                    tile.GetValidCol() * sizeof(T) % 32 == 0,
261	                    "Fix: For V2C(UB->L1), tile's valid column must be multiple of 32 bytes due to hardware "
262	                    "requirement.");
263	                uint32_t colIndex = tile.GetValidCol() * static_cast<size_t>(subBlockId);
264	                TINSERT_IMPL(matTile, tile, static_cast<uint16_t>(0), static_cast<uint16_t>(colIndex));
265	            }
266	        }
267	
268	        template <typename TileProd>
269	        PTO_INTERNAL void pushAcc2GMFiFo(RingFiFo& fifo, TileProd& tile)
270	        {
271	            using T = typename TileProd::DType;
272	            int ValidC = tile.GetValidCol();
273	            int ValidR = tile.GetValidRow();
274	            using GlobalStride = pto::Stride<1, 1, 1, -1, 1>;
275	            using GlobalShape = pto::Shape<1, 1, 1, -1, -1>;
276	            using GlobalData = GlobalTensor<T, GlobalShape, GlobalStride>;
277	            size_t entryBase = (tileIndex % RingFiFo::SLOT_NUM) * RingFiFo::SLOT_SIZE;
278	            __gm__ T* addr = (__gm__ T*)((uint64_t)fifo.GM_SLOT_BUFFER + entryBase + entryOffset);
279	            GlobalData gmData(addr, GlobalShape(ValidR, ValidC), GlobalStride(ValidC));
280	            if constexpr (EN_UNIT_FLAG) {
281	                TSTORE_IMPL<TileProd, GlobalData, AtomicType::AtomicNone, STPhase::Final>(gmData, tile);
282	            } else { // disable unit flag
283	                TSTORE_IMPL(gmData, tile);
284	            }
285	        }
286	
287	        template <typename TileProd, TileSplitAxis Split>
288	        PTO_INTERNAL void pushVec2GMFiFo(RingFiFo& fifo, TileProd& tile, int32_t subBlockId)
289	        {
290	            using T = typename TileProd::DType;
291	            constexpr int splitNum = 2;
292	            const int gmValidR = tile.GetValidRow();
293	            const int gmValidC = tile.GetValidCol();
294	            const int gmStrideR = (Split == TileSplitAxis::TILE_LEFT_RIGHT) ? gmValidC * splitNum : gmValidC;
295	            size_t entryBase = (tileIndex % RingFiFo::SLOT_NUM) * RingFiFo::SLOT_SIZE;
296	            size_t subAIVOffset = 0;
297	            if constexpr (Split == TileSplitAxis::TILE_NO_SPLIT) {
298	                subAIVOffset = 0;
299	            } else if constexpr (Split == TileSplitAxis::TILE_UP_DOWN) {
300	                subAIVOffset = subBlockId * gmValidR * gmValidC * sizeof(T);
301	            } else { // TILE_LEFT_RIGHT
302	                subAIVOffset = subBlockId * gmValidC * sizeof(T);
303	            }
304	            using GlobalShape = pto::Shape<1, 1, 1, -1, -1>;
305	            using GlobalStride = pto::Stride<1, 1, 1, -1, 1>;
306	            using GlobalData = GlobalTensor<T, GlobalShape, GlobalStride>;
307	            __gm__ T* addr = (__gm__ T*)((uint64_t)fifo.GM_SLOT_BUFFER + entryBase + subAIVOffset + entryOffset);
308	            GlobalData globalData(addr, GlobalShape(gmValidR, gmValidC), GlobalStride(gmStrideR));
309	            TSTORE_IMPL(globalData, tile);
