371	        template <typename TileProd, typename TConfig>
372	        PTO_INTERNAL void pushAcc2VecFiFo(RingFiFo& fifo, TileProd& tile)
373	        {
374	            using T = FixpipeConsType<TileProd, TConfig>;
375	            using TileCons = FixpipeVecTile<TileProd, T, TConfig::LayoutMode>;
376	            TileCons consTile;
377	            uint64_t entryBase = (tileIndex % RingFiFo::SLOT_NUM) * RingFiFo::SLOT_SIZE;
378	            TASSIGN(consTile, (uint64_t)(fifo.C2V_CONSUMER_BUF + entryBase + entryOffset));
379	            TMovCcToUb<
380	                TileCons, TileProd, (AccToVecMode) static_cast<uint8_t>(TConfig::SubBlockId), TConfig::QuantPre,
381	                TConfig::ReluMode, TConfig::Phase>(
382	                consTile.data(), tile.data(), tile.GetValidRow(), tile.GetValidCol());
383	        }
