385	        template <typename TileProd, typename TConfig>
386	        PTO_INTERNAL void pushAcc2GMFiFo(RingFiFo& fifo, TileProd& tile)
387	        {
388	            using T = FixpipeConsType<TileProd, TConfig>;
389	            using GlobalData = FixpipeGlobalData<TileProd, TConfig>;
390	            using GlobalShape = pto::Shape<1, 1, 1, -1, -1>;
391	            using GlobalStride = pto::Stride<1, 1, 1, -1, 1>;
392	            size_t entryBase = (tileIndex % RingFiFo::SLOT_NUM) * RingFiFo::SLOT_SIZE;
393	            __gm__ T* addr = (__gm__ T*)((uint64_t)fifo.GM_SLOT_BUFFER + entryBase + entryOffset);
394	            GlobalData globalTensor(
395	                addr, GlobalShape(tile.GetValidRow(), tile.GetValidCol()), GlobalStride(tile.GetValidCol()));
396	
397	            if constexpr (TConfig::AtomicT == AtomicType::AtomicAdd) {
398	                SetAtomicAdd<typename GlobalData::DType>();
399	            }
400	            TStoreAcc<GlobalData, TileProd, TConfig::QuantPre, TConfig::ReluMode, TConfig::Phase>(
401	                globalTensor.data(), tile.data(), globalTensor.GetShape(GlobalTensorDim::DIM_0),
402	                globalTensor.GetShape(GlobalTensorDim::DIM_1), globalTensor.GetShape(GlobalTensorDim::DIM_2),
403	                globalTensor.GetShape(GlobalTensorDim::DIM_3), globalTensor.GetShape(GlobalTensorDim::DIM_4),
404	                globalTensor.GetStride(GlobalTensorDim::DIM_0), globalTensor.GetStride(GlobalTensorDim::DIM_1),
405	                globalTensor.GetStride(GlobalTensorDim::DIM_2), globalTensor.GetStride(GlobalTensorDim::DIM_3),
406	                globalTensor.GetStride(GlobalTensorDim::DIM_4), tile.GetValidRow(), tile.GetValidCol());
407	            if constexpr (TConfig::AtomicT == AtomicType::AtomicAdd) {
408	                set_atomic_none();
409	            }
410	        }
