583	        template <typename TileCons, TileSplitAxis Split>
584	        PTO_INTERNAL void popVecTileFromGMFiFo(RingFiFo& fifo, TileCons& tile, int32_t subBlockId)
585	        {
586	            using T = typename TileCons::DType;
587	            size_t gmStrideR = tile.GetValidCol();
588	            constexpr int splitNum = 2;
589	            if constexpr (Split == TileSplitAxis::TILE_LEFT_RIGHT) {
590	                gmStrideR = splitNum * tile.GetValidCol();
591	            } else if constexpr (Split == TileSplitAxis::TILE_LEFT_RIGHT_ODD) {
592	                gmStrideR = splitNum * tile.GetValidCol() + 2 * subBlockId - 1;
593	            } else {
594	                gmStrideR = tile.GetValidCol();
595	            }
596	            // global tensor
597	            size_t subAIVOffset = 0;
598	            if constexpr (Split == TileSplitAxis::TILE_NO_SPLIT) {
599	                subAIVOffset = 0; // TILE_NO_SPLIT : single reader, no offset needed
600	            } else if constexpr (Split == TileSplitAxis::TILE_UP_DOWN) {
601	                subAIVOffset = subBlockId * tile.GetValidRow() * tile.GetValidCol() * sizeof(T);
602	            } else if constexpr (Split == TileSplitAxis::TILE_LEFT_RIGHT) {
603	                subAIVOffset = subBlockId * tile.GetValidCol() * sizeof(T);
604	            } else if constexpr (Split == TileSplitAxis::TILE_UP_DOWN_ODD) {
605	                subAIVOffset = subBlockId * (tile.GetValidRow() + subBlockId) * tile.GetValidCol() * sizeof(T);
606	            } else if constexpr (Split == TileSplitAxis::TILE_LEFT_RIGHT_ODD) {
607	                subAIVOffset = subBlockId * (tile.GetValidCol() + subBlockId) * sizeof(T);
608	            }
609	            size_t entryBase = (static_cast<size_t>(tileIndex) % RingFiFo::SLOT_NUM) * RingFiFo::SLOT_SIZE;
610	            __gm__ T* addr = (__gm__ T*)((uint64_t)fifo.GM_SLOT_BUFFER + entryBase + subAIVOffset + entryOffset);
611	
612	            using GlobalStride = pto::Stride<1, 1, 1, -1, 1>;
613	            using GlobalShape = pto::Shape<1, 1, 1, -1, -1>;
614	            using GlobalData = GlobalTensor<T, GlobalShape, GlobalStride>;
615	            GlobalData globalData(addr, GlobalShape(tile.GetValidRow(), tile.GetValidCol()), GlobalStride(gmStrideR));
616	
617	            // local vector tile
618	            uint64_t localTileBase =
619	                fifo.C2V_CONSUMER_BUF + (static_cast<size_t>(tileIndex) % RingFiFo::LOCAL_SLOT_NUM) * TileCons::Rows *
620	                                            TileCons::Cols * sizeof(T);
621	            TASSIGN_IMPL(tile, localTileBase);
622	            TLOAD_IMPL(tile, globalData);
623	        }
624	
625	        template <typename TileCons, TileSplitAxis Split>
626	        PTO_INTERNAL void popMatTileFromGMFiFo(RingFiFo& fifo, TileCons& tile)
627	        {
628	            using T = typename TileCons::DType;
629	            size_t entryBase = (static_cast<size_t>(tileIndex) % RingFiFo::SLOT_NUM) * RingFiFo::SLOT_SIZE;
630	            __gm__ T* addr = (__gm__ T*)((uint64_t)fifo.GM_SLOT_BUFFER + entryBase + entryOffset);
631	            using GlobalStride = pto::Stride<1, 1, 1, -1, 1>;
632	            using GlobalShape = pto::Shape<1, 1, 1, -1, -1>;
633	            using GlobalData = GlobalTensor<T, GlobalShape, GlobalStride>;
634	            GlobalData globalT(
635	                addr, GlobalShape(tile.GetValidRow(), tile.GetValidCol()), GlobalStride(tile.GetValidCol()));
636	
637	            uint64_t localTileBase =
638	                fifo.V2C_CONSUMER_BUF + (static_cast<size_t>(tileIndex) % RingFiFo::LOCAL_SLOT_NUM) * TileCons::Rows *
639	                                            TileCons::Cols * sizeof(T);
640	            TASSIGN_IMPL(tile, localTileBase);
641	            TLOAD_IMPL(tile, globalT);
642	        }
