652	        template <typename TileCons, TileSplitAxis Split>
653	        PTO_INTERNAL bool pop(RingFiFo& fifo, TileCons& tile, int32_t subBlockId)
654	        {
655	            static_assert(
656	                TileCons::Loc == TileType::Vec || TileCons::Loc == TileType::Mat || TileCons::Loc == TileType::Ctrl,
657	                "Fix: TPOP has unsupported tile type!");
658	            if constexpr (TileCons::Loc == TileType::Vec) {
659	                if constexpr (is_c2v_ub || is_both) {
660	                    popTileFromVecFiFo<TileCons, Split>(fifo, tile);
661	                    return false;
662	                } else if constexpr (is_c2v_gm) {
663	                    popVecTileFromGMFiFo<TileCons, Split>(fifo, tile, subBlockId);
664	                    return true;
665	                }
666	            } else if constexpr (TileCons::Loc == TileType::Mat) {
667	                if constexpr (is_v2c_mat || is_both) {
668	                    popTileFromMatFiFo<TileCons, Split>(fifo, tile);
669	                    return false;
670	                } else if constexpr (is_v2c_gm) {
671	                    popMatTileFromGMFiFo<TileCons, Split>(fifo, tile);
672	                    return true;
673	                }
674	            } else { // pop ctrl tile
675	                popCtrlFromCtrlFiFo(fifo, tile);
676	                return false;
677	            }
678	        }
