710	/**
711	 * TPUSH: Push Tile to FIFO
712	 * * Flow:
713	 * 1. [Alloc]   Check GM space (Cross-Core)
714	 * 2. [Store]   Write data to GM
715	 * 3. [Commit]  Signal Consumer (Cross-Core)
716	 */
717	template <typename Pipe, typename TileProd, TileSplitAxis Split, std::enable_if_t<is_tile_data_v<TileProd>, int> = 0>
718	PTO_INTERNAL void TPUSH_IMPL(Pipe& pipe, TileProd& tile)
719	{
720	    // 1. Cross-Core: Wait for space
721	    bool isAllocate = pipe.prod.getAllocateStatus() && Pipe::shouldWaitFree(pipe.prod.tileIndex);
722	    if (isAllocate) {
723	        pipe.prod.template allocate<Split>();
724	    }
725	
726	    // 2. Address Calculation
727	    if constexpr (Split == TileSplitAxis::TILE_NO_SPLIT) {
728	        pipe.prod.template push<TileProd, Split>(pipe.fifo, tile, 0);
729	    } else {
730	        pipe.prod.template push<TileProd, Split>(pipe.fifo, tile, get_subblockid());
731	    }
732	    pipe.prod.tileIndex++;
733	
734	    // 3. Cross-Core: Commit & Signal
735	    bool isRecord = pipe.prod.getRecordStatus();
736	    if (isRecord) {
737	        pipe.prod.template record<Split>();
738	    }
739	}
740	
741	template <typename Pipe, typename TileProd, TileSplitAxis Split>
742	PTO_INTERNAL void TPUSH_IMPL(Pipe& pipe, TileProd& tile, int32_t subBlockId)
743	{
744	    // 1. Cross-Core: Wait for space
745	    bool isAllocate = pipe.prod.getAllocateStatus() && Pipe::shouldWaitFree(pipe.prod.tileIndex);
746	    if (isAllocate) {
747	        pipe.prod.template allocate<Split>();
748	    }
749	
750	    // 2. Address Calculation
751	    pipe.prod.template push<TileProd, Split>(pipe.fifo, tile, subBlockId);
752	    pipe.prod.tileIndex++;
753	
754	    // 3. Cross-Core: Commit & Signal
755	    bool isRecord = pipe.prod.getRecordStatus();
756	    if (isRecord) {
757	        pipe.prod.template record<Split>();
758	    }
759	}
