796	struct TMPipe {
797	    static constexpr uint8_t FlagIDPlusOne = FlagID + 1;
798	    static constexpr bool is_c2v_gm =
799	        (FiFoType == FIFOType::GM_FIFO) && (TileDataProd::Loc == TileType::Acc) && (TileDataCons::Loc == TileType::Vec);
800	    static constexpr bool is_c2v_ub = (FiFoType == FIFOType::VEC_FIFO) && (TileDataProd::Loc == TileType::Acc) &&
801	                                      (TileDataCons::Loc == TileType::Vec);
802	    static constexpr bool is_c2v = is_c2v_gm || is_c2v_ub;
803	    static constexpr bool is_v2c_gm =
804	        (FiFoType == FIFOType::GM_FIFO) && (TileDataProd::Loc == TileType::Vec) && (TileDataCons::Loc == TileType::Mat);
805	    static constexpr bool is_v2c_mat = (FiFoType == FIFOType::MAT_FIFO) && (TileDataProd::Loc == TileType::Vec) &&
806	                                       (TileDataCons::Loc == TileType::Mat);
807	    static constexpr bool is_v2c_ctrl = (FiFoType == FIFOType::CTRL_FIFO) && (TileDataProd::Loc == TileType::Vec) &&
808	                                        (TileDataCons::Loc == TileType::Ctrl);
809	    static constexpr bool is_v2c = is_v2c_gm || is_v2c_mat || is_v2c_ctrl;
810	    static_assert(
811	        is_c2v || is_v2c,
812	        "TPipe currently only supports Cube-to-Vec or Vec-to-Cube communication with specified tile and FIFO types.");
813	    static constexpr int VEC_CORE_ID_OFFSET = 16;
814	    static_assert(
815	        FlagIDPlusOne < 16, "Fix: With single direction, FlagID + 1 must be less than 16 due to hardware limit.");
816	
817	    using DataFiFo = std::conditional_t<
818	        (FiFoType == FIFOType::GM_FIFO),
819	        DataFIFO<typename TileDataCons::DType, FiFoType, FiFoDepth, FiFoSyncT, LocalFiFoDepth>,
820	        DataFIFO<TileDataCons, FiFoType, FiFoDepth, FiFoSyncT>>;
