823	    // Producer Interface
824	    // -------------------------------------------------------------------------
825	    struct Producer {
826	        int tile_id = 0;
827	        int sub_tile_id = 0;
828	        bool isAllocate = true;
829	        bool isRecord = true;
830	        int entryOffset = 0;
831	
832	        PTO_INTERNAL Producer() = default;
833	
834	        PTO_INTERNAL void setTileId(int t_id, int sub_t_id)
835	        {
836	            tile_id = t_id;
837	            sub_tile_id = sub_t_id;
838	        }
