844	        PTO_INTERNAL void setAllocateStatus(bool allocate) { isAllocate = allocate; }
845	
846	        PTO_INTERNAL bool getAllocateStatus() const { return isAllocate; }
847	
848	        PTO_INTERNAL void setRecordStatus(bool record) { isRecord = record; }
