854	        /**
855	         * alloc: Request space in FIFO
856	         * 1. (iter >= Depth): Startup protection. Don't check flags when buffer is empty.
857	         * 2. (iter % Period == 0): Sparse sync. Only check flag periodically.
858	         */
859	        PTO_INTERNAL void allocate() const
860	        {
861	            if constexpr (is_c2v) {
862	                // Cube producer waits for Vec consumer to free buffer
863	                // Vec signals on flag_id+1 only, but Cube must wait on BOTH
864	                // (because Vec0 signals flag_id+1, Vec1 signals flag_id+1+16 from Cube's view)
865	#ifdef __DAV_CUBE__
866	                wait_intra_block(PIPE_FIX, FlagIDPlusOne);
867	                wait_intra_block(PIPE_FIX, FlagIDPlusOne + VEC_CORE_ID_OFFSET);
868	#endif
869	            } else if constexpr (is_v2c_gm || is_v2c_mat) {
870	                // is_v2c (both gm and mat)
871	                // Vec producer waits for Cube consumer to free buffer
872	                // Cube signals on BOTH, Vec waits on flag_id+1 only
873	#ifdef __DAV_VEC__
874	                wait_intra_block(PIPE_MTE3, FlagIDPlusOne);
875	#endif
876	            } else if constexpr (is_v2c_ctrl) {
877	                // is_v2c_ctrl
878	                // Control signals from Vec to Cube: Vec signals on flag_id, Cube waits on flag_id only
879	#ifdef __DAV_VEC__
880	                wait_intra_block(PIPE_S, FlagIDPlusOne);
881	#endif
882	            }
883	        }
884	
885	        // Forward dependency: record (producer) and wait (consumer)
886	        /**
887	         * record - Producer signals that data is ready
888	         * Called by the producer after completing the operation (TSTORE_C2GM or TSTORE_V2GM)
889	         */
890	        PTO_INTERNAL void record() const
891	        {
892	            if constexpr (is_c2v) {
893	#ifdef __DAV_CUBE__
894	                // Cube -> Vec: Cube sets BOTH flags on PIPE_FIX
895	                set_intra_block(PIPE_FIX, FlagID);
896	                set_intra_block(PIPE_FIX, FlagID + VEC_CORE_ID_OFFSET);
897	#endif
898	            } else if constexpr (is_v2c_gm || is_v2c_mat) { // is_v2c (both gm and mat)
899	                // Vec -> Cube: Vec sets flag_id only on PIPE_MTE3
900	                // Each Vec subblock executes this; hardware maps subblock 1's flag to flag_id+16
901	                set_intra_block(PIPE_MTE3, FlagID);
902	            } else { // is_v2c_ctrl
903	                // Control signals from Vec to Cube: Vec signals on flag_id, Cube waits on flag_id only
904	                set_intra_block(PIPE_S, FlagID);
905	            }
906	        }
