908	        template <typename T, int ProdM, int ProdN, int ConsM, int ConsN>
909	        PTO_INTERNAL void pushAcc2GMFiFo(DataFiFo& fifo, TileDataProd& tile)
910	        {
911	            // calculate base address in GM FIFO for this tile
912	            constexpr int kTileFactor = ConsN / ProdN;
913	            uint32_t bufIndex = static_cast<uint32_t>(tile_id % DataFiFo::fifoDepth);
914	            size_t entryBase = bufIndex * kTileFactor * ProdM * ProdN * sizeof(T);
915	            using GlobalData = GlobalTensor<T, pto::Shape<1, 1, 1, ProdM, ProdN>, pto::Stride<1, 1, 1, ProdN, 1>>;
916	            GlobalData globalTensor((__gm__ T*)((uint64_t)fifo.fifoBase + entryBase + entryOffset));
917	            // store tile to GM FIFO, enable unit-flag or disable unit-flag
918	            if constexpr (EN_UNIT_FLAG) {
919	                TSTORE_IMPL<TileDataProd, GlobalData, AtomicType::AtomicNone, STPhase::Final>(globalTensor, tile);
920	            } else { // disable unit flag
921	                TSTORE_IMPL(globalTensor, tile);
922	            }
923	        }
