925	        template <typename T, int ProdM, int ProdN, int ConsM, int ConsN, int VEC_CORES>
926	        PTO_INTERNAL void pushAcc2VecFiFo(DataFiFo& fifo, TileDataProd& tile)
927	        {
928	            static_assert(
929	                (TileDataProd::Loc == TileType::Acc) && (DataFiFo::fifoType == FIFOType::VEC_FIFO),
930	                "Fix: TPUSH has unsupported fifo type!");
931	            constexpr bool isSplitM = (ProdM != ConsM && ProdN == ConsN && VEC_CORES == 2);
932	            constexpr bool isSplitN = (ProdM == ConsM && ProdN != ConsN && VEC_CORES == 2);
933	            constexpr bool nonSplit = (ProdM == ConsM && ProdN == ConsN && VEC_CORES == 1);
934	            // Note: make sure the vecTile is stored in VEC_FIFO continuously.
935	            // dual vector cores(1c:2v)
936	            if constexpr (isSplitM) {
937	                // split M between two vectors
938	                constexpr int kTileFactor = ConsN / ProdN;
939	                constexpr uint32_t VecM = ProdM / VEC_CORES / kTileFactor;
940	                using TileDataVec = Tile<TileType::Vec, T, VecM, ProdN, BLayout::RowMajor, VecM, ProdN>;
941	                TileDataVec vecTile;
942	                uint64_t entryBase = (tile_id % DataFiFo::fifoDepth) * VecM * ProdN * sizeof(T);
943	                TASSIGN(vecTile, fifo.fifoBase + entryBase + entryOffset);
944	                TMOV_IMPL<TileDataVec, TileDataProd, AccToVecMode::DualModeSplitM>(vecTile, tile);
945	            } else if constexpr (isSplitN) {
946	                // split N between two vectors
947	                constexpr int kTileFactor = ConsN / ProdN;
948	                constexpr uint32_t VecN = ProdN / VEC_CORES / kTileFactor;
949	                using TileDataVec = Tile<TileType::Vec, T, ProdM, VecN, BLayout::RowMajor, ProdM, VecN>;
950	                TileDataVec vecTile;
951	                uint64_t entryBase = (tile_id % DataFiFo::fifoDepth) * ProdM * VecN * sizeof(T);
952	                TASSIGN(vecTile, fifo.fifoBase + entryBase + entryOffset);
953	                TMOV_IMPL<TileDataVec, TileDataProd, AccToVecMode::DualModeSplitN>(vecTile, tile);
954	            } else if constexpr (nonSplit) {
955	                // single vector core (1v:1v)
956	                TileDataCons vecTile;
957	                uint64_t entryBase = (tile_id % DataFiFo::fifoDepth) * ProdM * ProdN * sizeof(T);
958	                TASSIGN(vecTile, fifo.fifoBase + entryBase + entryOffset);
959	                TMOV_IMPL<TileDataCons, TileDataProd, AccToVecMode::SingleModeVec0>(vecTile, tile);
960	            } else {
961	                static_assert(
962	                    isSplitM || isSplitN || nonSplit, "Fix: TPUSH(pushAcc2VecFiFo) has unsupported split mode!");
963	            }
964	        }
