966	        template <typename T, int ProdM, int ProdN, int ConsM, int ConsN>
967	        PTO_INTERNAL void pushVec2GMFiFo(DataFiFo& fifo, TileDataProd& tile)
968	        {
969	            static_assert(DataFiFo::fifoType == FIFOType::GM_FIFO, "Fix: TPUSH: unsupported fifoType!");
970	            // calculate base address in GM FIFO for this tile
971	            constexpr int kTileFactor = ProdN / ConsN;
972	            uint32_t bufIndex = static_cast<uint32_t>(tile_id % DataFiFo::fifoDepth);
973	            size_t entryBase = bufIndex * kTileFactor * ConsM * ConsN * sizeof(T);
974	            using GlobalDataSub = GlobalTensor<T, pto::Shape<1, 1, 1, ProdM, ConsN>, pto::Stride<1, 1, 1, ConsN, 1>>;
975	            using TileDataSub = Tile<TileType::Vec, T, ProdM, ProdN, BLayout::RowMajor, ProdM, ConsN>;
976	            TileDataSub subTile;
977	            __gm__ T* addr = (__gm__ T*)((uint64_t)fifo.fifoBase + entryBase + entryOffset);
978	            // store tile to GM FIFO in sub-tiles if needed (when Tile_S1 > Cube_S1)
979	            for (int sub_col = 0; sub_col < kTileFactor; ++sub_col) {
980	                __gm__ T* addrSub = addr + sub_col * ConsM * ConsN;
981	                GlobalDataSub globalDataSub((__gm__ T*)(addrSub));
982	                uint64_t col_byte_offset = static_cast<uint64_t>(sub_col * ConsN * sizeof(T));
983	                TASSIGN_IMPL(subTile, (uint64_t)tile.data() + col_byte_offset);
984	                TSTORE_IMPL(globalDataSub, subTile);
985	            }
986	        }
