988	        template <typename T, int ProdM, int ProdN, int ConsM, int ConsN, int VEC_CORES>
989	        PTO_INTERNAL void pushVec2MatFiFo(DataFiFo& fifo, TileDataProd& tile)
990	        {
991	            static_assert(
992	                (TileDataProd::Loc == TileType::Vec) && (DataFiFo::fifoType == FIFOType::MAT_FIFO),
993	                "Fix: TPUSH has unsupported fifo type!");
994	            constexpr bool isSplitM = (ProdM != ConsM && ProdN == ConsN && VEC_CORES == 2);
995	            constexpr bool isSplitN = (ProdM == ConsM && ProdN != ConsN && VEC_CORES == 2);
996	            constexpr bool nonSplit = (ProdM == ConsM && ProdN == ConsN && VEC_CORES == 1);
997	            // dual vector cores
998	            if constexpr (isSplitM) {
999	                // split M between vectors
1000	                constexpr uint32_t VecM = ConsM / VEC_CORES;
1001	                int row_offset = VecM * static_cast<size_t>(get_subblockid());
1002	                uint64_t entryBase = (tile_id % DataFiFo::fifoDepth) * ConsM * ConsN * sizeof(T);
1003	                TileDataCons matTile;
1004	                TASSIGN_IMPL(matTile, fifo.fifoBase + entryBase);
1005	                TINSERT_IMPL(matTile, tile, static_cast<uint16_t>(row_offset), static_cast<uint16_t>(0));
1006	            } else if constexpr (isSplitN) {
1007	                // split N between vectors
1008	                int col_index = ProdN * static_cast<size_t>(get_subblockid());
1009	                uint64_t entryBase = (tile_id % DataFiFo::fifoDepth) * ConsM * ConsN * sizeof(T);
1010	                TileDataCons matTile;
1011	                TASSIGN_IMPL(matTile, fifo.fifoBase + entryBase);
1012	                TINSERT_IMPL(matTile, tile, static_cast<uint16_t>(0), static_cast<uint16_t>(col_index));
1013	            } else if constexpr (nonSplit) {
1014	                // single vector core
1015	                TileDataCons matTile;
1016	                uint64_t entryBase = (tile_id % DataFiFo::fifoDepth) * ConsM * ConsN * sizeof(T);
1017	                TASSIGN_IMPL(matTile, fifo.fifoBase + entryBase);
1018	                TINSERT_IMPL(matTile, tile, static_cast<uint16_t>(0), static_cast<uint16_t>(0));
1019	            } else {
1020	                static_assert(
1021	                    isSplitM || isSplitN || nonSplit, "Fix: TPUSH(pushVec2MatFiFo) has unsupported split mode!");
1022	            }
1023	        }
