1025	        template <typename T, int ProdM, int ProdN, int ConsM, int ConsN>
1026	        PTO_INTERNAL void pushVec2CtrlFiFo(DataFiFo& fifo, TileDataProd& tile)
1027	        {
1028	            static_assert(
1029	                DataFiFo::fifoType == FIFOType::CTRL_FIFO, "Fix: TPUSH(pushVec2CtrlFiFo) has unsupported fifoType!");
1030	            uint32_t bufIndex = static_cast<uint32_t>(tile_id % DataFiFo::fifoDepth);
1031	            uint64_t entryBase = bufIndex * sizeof(uint32_t);
1032	            __ssbuf__ uint32_t* ctrlBuf = (__ssbuf__ uint32_t*)(fifo.fifoBase + entryBase + entryOffset);
1033	            uint32_t ctrlSignal = *(tile.data());
1034	            *(ctrlBuf) = ctrlSignal;
1035	        }
