1037	        PTO_INTERNAL void push(DataFiFo& fifo, TileDataProd& tile)
1038	        {
1039	            // get tile shape and valid shape
1040	            using T = typename TileDataProd::DType;
1041	            constexpr int ProdM = TileDataProd::Rows;
1042	            constexpr int ProdN = TileDataProd::Cols;
1043	            constexpr int ConsM = TileDataCons::Rows;
1044	            constexpr int ConsN = TileDataCons::Cols;
1045	            constexpr int VEC_CORES = (VCRatio == VecCubeRatio::V2C1_VECS) ? 2 : 1;
1046	
1047	            static_assert(
1048	                TileDataProd::Loc == TileType::Acc || TileDataProd::Loc == TileType::Vec,
1049	                "Fix: TPUSH has unsupported tile type!");
1050	            if constexpr (TileDataProd::Loc == TileType::Acc) {
1051	                static_assert(
1052	                    (DataFiFo::fifoType == FIFOType::GM_FIFO) || (DataFiFo::fifoType == FIFOType::VEC_FIFO),
1053	                    "Fix: TPUSH has unsupported fifo type!");
1054	                if constexpr (DataFiFo::fifoType == FIFOType::GM_FIFO) {
1055	                    pushAcc2GMFiFo<T, ProdM, ProdN, ConsM, ConsN>(fifo, tile);
1056	                } else if constexpr (DataFiFo::fifoType == FIFOType::VEC_FIFO) {
1057	                    pushAcc2VecFiFo<T, ProdM, ProdN, ConsM, ConsN, VEC_CORES>(fifo, tile);
1058	                }
1059	            } else if constexpr (TileDataProd::Loc == TileType::Vec) {
1060	                static_assert(
1061	                    DataFiFo::fifoType == FIFOType::GM_FIFO || DataFiFo::fifoType == FIFOType::MAT_FIFO ||
1062	                        DataFiFo::fifoType == FIFOType::CTRL_FIFO,
1063	                    "Fix: TPUSH has unsupported fifo type!");
1064	                if constexpr (DataFiFo::fifoType == FIFOType::GM_FIFO) {
1065	                    pushVec2GMFiFo<T, ProdM, ProdN, ConsM, ConsN>(fifo, tile);
1066	                } else if constexpr (DataFiFo::fifoType == FIFOType::MAT_FIFO) {
1067	                    pushVec2MatFiFo<T, ProdM, ProdN, ConsM, ConsN, VEC_CORES>(fifo, tile);
1068	                } else if constexpr (DataFiFo::fifoType == FIFOType::CTRL_FIFO) {
1069	                    pushVec2CtrlFiFo<T, ProdM, ProdN, ConsM, ConsN>(fifo, tile);
1070	                }
1071	            } // end of store
1072	        }
1073	    };
