1076	    // Consumer Interface
1077	    // -------------------------------------------------------------------------
1078	    struct Consumer {
1079	        int tile_id = 0;
1080	        int sub_tile_id = 0;
1081	        bool isWait = true;
1082	        bool isFree = true;
1083	        int entryOffset = 0;
1084	
1085	        PTO_INTERNAL Consumer() = default;
1086	
1087	        PTO_INTERNAL void setTileId(int tid, int sub_tid)
1088	        {
1089	            tile_id = tid;
1090	            sub_tile_id = sub_tid;
1091	        }
1092	
1093	        PTO_INTERNAL int getTileId() const { return tile_id; }
1094	
1095	        PTO_INTERNAL int getSubTileId() const { return sub_tile_id; }
1096	
1097	        PTO_INTERNAL void setWaitStatus(bool wait) { isWait = wait; }
1098	
1099	        PTO_INTERNAL bool getWaitStatus() const { return isWait; }
1100	
1101	        PTO_INTERNAL void setFreeStatus(bool free) { isFree = free; }
1102	
1103	        PTO_INTERNAL bool getFreeStatus() const { return isFree; }
1104	
1105	        PTO_INTERNAL void setEntryOffset(int offset) { entryOffset = offset; }
1106	
1107	        /**
1108	         * wait: Block until data is ready
1109	         * Consumers strictly wait for data (no sparse optimization for safety).
1110	         */
1111	        PTO_INTERNAL void wait() const
1112	        {
1113	            if constexpr (is_c2v_gm) {
1114	                // Cube -> Vec (GM path): Vec waits on PIPE_MTE2 (data loaded from GM)
1115	                wait_intra_block(PIPE_MTE2, FlagID);
1116	            } else if constexpr (is_c2v_ub) {
1117	                // Cube -> Vec (UB path): Vec waits on PIPE_V before vector ops on UB data
1118	                // Cube sets PIPE_FIX, Vec waits PIPE_V (Vec does vector ops, not TLOAD)
1119	#ifdef __DAV_VEC__
1120	                wait_intra_block(PIPE_V, FlagID);
1121	#endif
1122	            } else if constexpr (is_v2c_gm) {
1123	                // Vec -> Cube (GM path): Cube waits on PIPE_MTE2, BOTH flags
1124	                wait_intra_block(PIPE_MTE2, FlagID);
1125	                wait_intra_block(PIPE_MTE2, FlagID + VEC_CORE_ID_OFFSET);
1126	            } else if constexpr (is_v2c_mat) { // is_v2c_mat
1127	                                               // Vec -> Cube (UB path - TINSERT): Cube waits on PIPE_MTE1, BOTH flags
1128	#ifdef __DAV_CUBE__
1129	                wait_intra_block(PIPE_MTE1, FlagID);
1130	                wait_intra_block(PIPE_MTE1, FlagID + VEC_CORE_ID_OFFSET);
1131	#endif
1132	            } else { // is_v2c_ctrl
1133	                wait_intra_block(PIPE_S, FlagID);
1134	                wait_intra_block(PIPE_S, FlagID + VEC_CORE_ID_OFFSET);
1135	            }
1136	        }
1137	
1138	        /**
1139	         * free: Release space in FIFO
1140	         * 1. (iter >= Depth - Period): Silence at start. Don't signal if Producer
1141	         * is still enjoying the initial free buffer space.
1142	         * 2. (is_sync_step): Accumulate free slots and signal in batches.
1143	         */
1144	        PTO_INTERNAL void free() const
1145	        {
1146	            if constexpr (is_c2v_gm) {
1147	                // Vec consumer frees buffer for Cube - signals on PIPE_MTE2, flag_id+1 only
1148	#ifdef __DAV_VEC__
1149	                uint8_t freeCubeID = FlagIDPlusOne;
1150	                set_intra_block(PIPE_MTE2, freeCubeID);
1151	#endif
1152	            } else if constexpr (is_c2v_ub) {
1153	                // Vec consumer frees buffer for Cube - signals on PIPE_V, flag_id+1 only
1154	                // Vec signals after vector ops complete (PIPE_V)
1155	#ifdef __DAV_VEC__
1156	                uint8_t freeCubeID = FlagIDPlusOne;
1157	                set_intra_block(PIPE_V, freeCubeID);
1158	#endif
1159	            } else if constexpr (is_v2c_gm || is_v2c_mat) { // is_v2c (both gm and mat)
1160	                // Cube consumer frees buffer for Vec - signals BOTH flags on PIPE_MTE1
1161	#ifdef __DAV_CUBE__
1162	                uint8_t freeVec0ID = FlagIDPlusOne;
1163	                uint8_t freeVec1ID = FlagIDPlusOne + VEC_CORE_ID_OFFSET;
1164	                set_intra_block(PIPE_MTE1, freeVec0ID);
1165	                set_intra_block(PIPE_MTE1, freeVec1ID);
1166	#endif
1167	            } else { // is_v2c_ctrl
1168	                     // Control signals from Vec to Cube: Vec signals on flag_id, Cube waits on flag_id only
1169	#ifdef __DAV_CUBE__
1170	                uint8_t freeVec0ID = FlagIDPlusOne;
1171	                uint8_t freeVec1ID = FlagIDPlusOne + VEC_CORE_ID_OFFSET;
1172	                set_intra_block(PIPE_S, freeVec0ID);
1173	                set_intra_block(PIPE_S, freeVec1ID);
1174	#endif
1175	            }
1176	        }
