1178	        template <typename T, int ProdM, int ProdN, int ConsM, int ConsN>
1179	        PTO_INTERNAL void popVecTileFromGMFiFo(DataFiFo& fifo, TileDataCons& tile)
1180	        {
1181	            size_t bufIndex = static_cast<size_t>(tile_id) % fifo.fifoDepth;
1182	            constexpr int kTileFactor = ConsN / ProdN;
1183	            size_t entryBase = static_cast<size_t>(bufIndex) * kTileFactor * ProdM * ProdN * sizeof(T);
1184	            __gm__ T* addr = (__gm__ T*)((uint64_t)fifo.fifoBase + entryBase + entryOffset);
1185	
1186	            if constexpr (DataFiFo::useLocalFiFo) {
1187	                uint64_t localTileBase =
1188	                    (uint64_t)fifo.localFiFoBase +
1189	                    (static_cast<size_t>(tile_id) % fifo.localFiFoDepth) * ConsM * ConsN * sizeof(T);
1190	                TASSIGN_IMPL(tile, localTileBase);
1191	            }
1192	
1193	            using GlobalDataSub = GlobalTensor<T, pto::Shape<1, 1, 1, ConsM, ProdN>, pto::Stride<1, 1, 1, ProdN, 1>>;
1194	            using TileDataSub = Tile<TileType::Vec, T, ConsM, ConsN, BLayout::RowMajor, ConsM, ProdN>;
1195	            TileDataSub tileSub;
1196	            for (int sub_col = 0; sub_col < kTileFactor; ++sub_col) {
1197	                __gm__ T* addrSub = addr + sub_col * ProdM * ProdN;
1198	                uint64_t col_byte_offset = sub_col * ProdN * sizeof(T);
1199	                GlobalDataSub globalTensorSub(addrSub);
1200	                TASSIGN_IMPL(tileSub, (uint64_t)tile.data() + col_byte_offset);
1201	                TLOAD_IMPL(tileSub, globalTensorSub);
1202	            }
1203	        }
