1205	        template <typename T, int ProdM, int ProdN, int ConsM, int ConsN>
1206	        PTO_INTERNAL void popTileFromLocalFiFo(DataFiFo& fifo, TileDataCons& tile)
1207	        {
1208	            uint32_t bufIndex = static_cast<uint32_t>(tile_id % DataFiFo::fifoDepth);
1209	            size_t entryBase = bufIndex * ConsM * ConsN * sizeof(T);
1210	            uint64_t localTileBase = fifo.fifoBase + entryBase + entryOffset;
1211	            TASSIGN_IMPL(tile, localTileBase);
1212	        }
1213	
1214	        template <typename T, int ConsM, int ConsN, int ProdN>
1215	        PTO_INTERNAL void popMatTileFromGMFiFo(DataFiFo& fifo, TileDataCons& tile)
1216	        {
1217	            uint32_t bufIndex = static_cast<uint32_t>(tile_id % fifo.fifoDepth);
1218	            size_t entryBase = bufIndex * ConsM * ProdN * sizeof(T);
1219	            using GlobalData = GlobalTensor<T, pto::Shape<1, 1, 1, ConsM, ConsN>, pto::Stride<1, 1, 1, ConsN, 1>>;
1220	            GlobalData globalTensor((__gm__ T*)((uint64_t)fifo.fifoBase + entryBase + entryOffset));
1221	
1222	            if constexpr (DataFiFo::useLocalFiFo) {
1223	                uint64_t localTileBase =
1224	                    (uint64_t)fifo.localFiFoBase +
1225	                    (static_cast<size_t>(tile_id) % fifo.localFiFoDepth) * ConsM * ConsN * sizeof(T);
1226	                TASSIGN_IMPL(tile, localTileBase);
1227	            }
1228	            TLOAD_IMPL(tile, globalTensor);
1229	        }
1230	
1231	        PTO_INTERNAL void popCtrlFromCtrlFiFo(DataFiFo& fifo)
1232	        {
1233	            uint32_t bufIndex = static_cast<uint32_t>(tile_id % fifo.fifoDepth);
1234	            size_t entryBase = bufIndex * sizeof(uint32_t);
1235	            uint64_t ctrlTileBase = fifo.fifoBase + entryBase + entryOffset;
1236	            fifo.ctrlSignal = (*(__ssbuf__ uint32_t*)(ctrlTileBase) == 1) ? true : false;
1237	        }
1238	
1239	        PTO_INTERNAL bool pop(DataFiFo& fifo, TileDataCons& tile)
1240	        {
1241	            using T = typename TileDataCons::DType;
1242	            constexpr int ProdM = TileDataProd::Rows;
1243	            constexpr int ProdN = TileDataProd::Cols;
1244	            constexpr int ConsM = TileDataCons::Rows;
1245	            constexpr int ConsN = TileDataCons::Cols;
1246	            constexpr int VEC_CORES = (VCRatio == VecCubeRatio::V2C1_VECS) ? 2 : 1;
1247	
1248	            static_assert(
1249	                TileDataCons::Loc == TileType::Vec || TileDataCons::Loc == TileType::Mat,
1250	                "Fix: TPOP has unsupported tile type!");
1251	            if constexpr (TileDataCons::Loc == TileType::Vec) {
1252	                static_assert(
1253	                    (DataFiFo::fifoType == FIFOType::GM_FIFO) || (DataFiFo::fifoType == FIFOType::VEC_FIFO),
1254	                    "Fix: TPOP has unsupported fifo type!");
1255	                if constexpr (DataFiFo::fifoType == FIFOType::GM_FIFO) {
1256	                    popVecTileFromGMFiFo<T, ProdM, ProdN, ConsM, ConsN>(fifo, tile);
1257	                    return true;
1258	                } else if constexpr (DataFiFo::fifoType == FIFOType::VEC_FIFO) {
1259	                    return false;
1260	                } else if constexpr (DataFiFo::fifoType == FIFOType::CTRL_FIFO) {
1261	                    popCtrlFromCtrlFiFo(fifo);
1262	                    return false;
1263	                }
1264	            } else if constexpr (TileDataCons::Loc == TileType::Mat) {
1265	                static_assert(
1266	                    (DataFiFo::fifoType == FIFOType::GM_FIFO) || (DataFiFo::fifoType == FIFOType::MAT_FIFO),
1267	                    "Fix: TPOP has unsupported fifo type!");
1268	                if constexpr (DataFiFo::fifoType == FIFOType::GM_FIFO) {
1269	                    popMatTileFromGMFiFo<T, ConsM, ConsN, ProdN>(fifo, tile);
1270	                    return true;
1271	                } else if constexpr (DataFiFo::fifoType == FIFOType::MAT_FIFO) {
1272	                    return false;
1273	                }
1274	            }
1275	        }
1276	    };
1277	
1278	    DataFiFo fifo;
1279	    Producer prod;
1280	    Consumer cons;
1281	
1282	    // Constructors for GM_FIFO base address initialization
1283	    template <FIFOType T = FiFoType, typename std::enable_if_t<T == FIFOType::GM_FIFO, int> = 0>
1284	    PTO_INTERNAL explicit TMPipe(__gm__ typename TileDataCons::DType* gmFiFoBase, uint32_t localFiFoBase)
1285	        : fifo(gmFiFoBase, localFiFoBase), prod(), cons()
1286	    {
1287	        cons.free();
1288	    }
1289	
1290	    template <FIFOType T = FiFoType, typename std::enable_if_t<T != FIFOType::GM_FIFO, int> = 0>
1291	    PTO_INTERNAL explicit TMPipe(uint32_t fifoBase) : fifo(fifoBase), prod(), cons()
1292	    {
1293	        cons.free();
1294	    }
1295	
1296	    // Destructor for TPipe
1297	    PTO_INTERNAL ~TMPipe() { prod.allocate(); }
1298	};
1299	
1300	template <typename TileData, typename Pipe>
1301	PTO_INTERNAL void TPUSH_IMPL(TileData& tile, Pipe& pipe)
1302	{
1303	    // 1. Cross-Core: Wait for space
1304	    bool isAllocate = pipe.prod.getAllocateStatus();
1305	    if (isAllocate) {
1306	        pipe.prod.allocate();
1307	    }
1308	
1309	    // 2. Address Calculation
1310	    pipe.prod.push(pipe.fifo, tile);
1311	
1312	    // 3； Cross-Core: Commit & Signal
1313	    bool isRecord = pipe.prod.getRecordStatus();
1314	    if (isRecord) {
1315	        pipe.prod.record();
1316	    }
1317	}
1318	
1319	} // namespace pto
1320	
1321	#endif
1322

