257	        TMOV(aTile, aMatTile);
258	        TMOV(bTile, bMatTile);
259	
260	        set_flag(PIPE_MTE1, PIPE_M, EVENT_ID0);
261	        wait_flag(PIPE_MTE1, PIPE_M, EVENT_ID0);
262	
263	        TMATMUL(accTile, aTile, bTile);
264	
265	        set_flag(PIPE_M, PIPE_FIX, EVENT_ID0);
266	        wait_flag(PIPE_M, PIPE_FIX, EVENT_ID0);
267	
268	        // The Acc producer path never looks at the sub-block ID; the split axis
269	        // only decides how many vector cores are signalled.
270	        TPUSH<MatPipe, AccTile, SplitAxis>(mPipe, accTile);
271	
272	        pipe_barrier(PIPE_ALL);
273	    }
274	
275	    if constexpr (DAV_VEC) {
276	        const uint32_t subBlockIdx = get_subblockid();
277	        // TILE_NO_SPLIT only signals sub-block 0, so AIV1 must stay out of the pipe.
278	        bool isConsumer = true;
279	        if constexpr (IS_NO_SPLIT) {
280	            isConsumer = (subBlockIdx == 0);
281	        }
282	
283	        if (isConsumer) {
284	            VecTileCons vecTile; // TPOP assigns the UB address from the local FIFO base
285	
286	            if constexpr (ExplicitId) {
287	                // Hand each core its peer's ID: the caller supplied value must be
288	                // the one the FIFO address arithmetic uses.
289	                TPOP<MatPipe, VecTileCons, SplitAxis>(mPipe, vecTile, static_cast<int32_t>(1 - subBlockIdx));
290	            } else {
291	                TPOP<MatPipe, VecTileCons, SplitAxis>(mPipe, vecTile);
292	            }
293	
294	            set_flag(PIPE_MTE2, PIPE_MTE3, EVENT_ID0);
295	            wait_flag(PIPE_MTE2, PIPE_MTE3, EVENT_ID0);
296	
297	            GlobalOut globalOut(out + subBlockIdx * CONS_M * N);
298	            TSTORE(globalOut, vecTile);
299	
300	            pipe_barrier(PIPE_ALL);
301	        }
302	    }
303	}
304	
305	template <int32_t tilingKey>
306	void LaunchTPushPopSubBlockDispatchV2C(uint8_t* out, uint8_t* srcA, uint8_t* srcB, void* stream)
307	{
